// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 10 ether);
        c.seedMarket{value: 1 ether}(1000000);

        address user1 = address(0x1);
        vm.deal(user1, 10 ether);
        vm.prank(user1);
        c.buyDrugs{value: 1 ether}();

        address user2 = address(0x2);
        vm.deal(user2, 10 ether);
        vm.prank(user2);
        c.buyDrugs{value: 1 ether}();

        vm.warp(block.timestamp + 100000);

        vm.prank(user2);
        c.collectDrugs(user1);

        vm.prank(c.ceoAddress());
        c.DrugDealer();

        assertTrue(c.claimedDrugs(user1) > 0);
    }
}
